<template><div><PageHeader eyebrow="Enterprise Detail" title="订单与流水" :description="`${enterprise?.name||'企业'} · 财务记录统一查询`"><button class="layui-btn monitor-secondary" @click="exportCsv">导出当前记录</button></PageHeader><EnterpriseNav/><section class="panel"><div class="summary-strip"><div class="summary-item"><span>账户余额</span><strong>{{money(summary.balance)}}</strong></div><div class="summary-item"><span>累计充值</span><strong>{{money(summary.totalRecharge)}}</strong></div><div class="summary-item"><span>累计套餐支出</span><strong>{{money(summary.totalSubscriptionExpense)}}</strong></div><div class="summary-item"><span>本月流水笔数</span><strong>{{summary.monthTransactionCount}}</strong></div></div></section><div class="finance-tabs" role="tablist"><button v-for="tab in tabs" :key="tab.key" :class="{active:active===tab.key}" @click="switchTab(tab.key)">{{tab.label}}</button></div><section class="panel"><header class="panel-header"><div><h2>{{activeTab.label}}</h2><p>财务信息可查看，不提供修改订单功能</p></div><span class="tag success">共 {{result.total}} 条</span></header><div v-if="loading" class="loading-state">正在加载财务记录…</div><div v-else-if="!result.list.length" class="empty-state">暂无记录。</div><template v-else><div class="table-wrap"><table class="layui-table monitor-table"><thead><tr><th>业务编号</th><th>业务类型</th><th>金额</th><th>状态/余额</th><th>关联信息</th><th>发生时间</th></tr></thead><tbody><tr v-for="item in result.list" :key="item.id"><td>{{item.orderNo||item.transactionNo}}</td><td>{{typeText(item)}}</td><td>{{money(item.amount)}}</td><td>{{statusText(item)}}</td><td>{{item.channel||item.referenceNo||`${item.startedAt} 至 ${item.endedAt}`}}</td><td>{{item.paidAt||item.createdAt}}</td></tr></tbody></table></div><AppPagination :page-no="result.pageNo" :page-size="result.pageSize" :total="result.total" @change="changePage" /></template></section></div></template>
<script>import PageHeader from '@/components/PageHeader.vue';import AppPagination from '@/components/AppPagination.vue';import EnterpriseNav from './EnterpriseNav.vue';import { enterpriseApi } from '@/api/monitor';export default{name:'EnterpriseFinancePage',components:{PageHeader,AppPagination,EnterpriseNav},data:()=>({enterprise:null,summary:{},tabs:[{key:'recharge-orders',label:'充值订单'},{key:'subscription-orders',label:'订阅订单'},{key:'wallet-transactions',label:'钱包流水'}],active:'recharge-orders',result:{list:[],pageNo:1,pageSize:10,total:0},loading:false}),computed:{id(){return Number(this.$route.params.id);},activeTab(){return this.tabs.find(i=>i.key===this.active);}},mounted(){enterpriseApi.detail(this.id).then(d=>{this.enterprise=d;});enterpriseApi.financeSummary(this.id).then(d=>{this.summary=d;});this.load();},methods:{money:v=>`${Number(v)<0?'- ':''}¥ ${Math.abs(Number(v||0)).toLocaleString('zh-CN',{minimumFractionDigits:2})}`,typeText(i){return i.planName||({RECHARGE:'账户充值',BUY_PLAN:'购买套餐',ADJUST:'后台调整'}[i.type])||'账户充值';},statusText(i){return i.balanceAfter!==undefined?`余额 ${this.money(i.balanceAfter)}`:i.status===2?'已完成':'处理中';},async load(){this.loading=true;try{this.result=await enterpriseApi.finance(this.id,this.active,{pageNo:this.result.pageNo,pageSize:this.result.pageSize});}finally{this.loading=false;}},switchTab(key){this.active=key;this.result.pageNo=1;this.load();},changePage(pageNo){this.result.pageNo=pageNo;this.load();},exportCsv(){const rows=[['业务编号','类型','金额','发生时间'],...this.result.list.map(i=>[i.orderNo||i.transactionNo,this.typeText(i),i.amount,i.paidAt||i.createdAt])];const b=new Blob(['\ufeff'+rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`${this.activeTab.label}.csv`;a.click();URL.revokeObjectURL(a.href);}}};</script><style scoped>.finance-tabs{display:flex;gap:4px;margin:16px 0 8px}.finance-tabs button{min-height:42px;padding:0 18px;border:0;border-bottom:2px solid transparent;color:var(--muted);background:transparent}.finance-tabs button.active{border-color:var(--primary);color:var(--primary);font-weight:700}</style>
